sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // On load of a saved record, keep the stored values
    if (isLoading && !g_form.isNewRecord()) {
        return;
    }
    if (newValue === '') {
        g_form.clearValue('department');
        g_form.clearValue('email');
        return;
    }
    // Copy department and email from the selected caller
    g_form.getReference('caller', function (caller) {
        g_form.setValue('department', caller.department);
        g_form.setValue('email', caller.email);
    });
}
